/**
 * SAK-T01 — Eliza Framework Adapter
 *
 * Maps LangChain DynamicStructuredTool-style definitions (as generated by
 * NexusToolkit.getLangChainTools) into Eliza OS action payloads so that
 * Nexus Intelligence agent tools can be used inside Eliza conversational
 * agents without manual schema translation.
 *
 * Eliza action schema reference:
 *   https://elizaos.github.io/eliza/docs/core/actions
 *
 * @example
 * import { AgentKit } from '@nexus-intelligence-xyz/sdk'
 * import { elizaAdapter } from '@nexus-intelligence-xyz/sdk/tools/eliza_adapter'
 *
 * const kit = new AgentKit(config)
 * const langchainTools = kit.getLangChainTools(sessionId)
 * const elizaActions = elizaAdapter(langchainTools)
 * // Register elizaActions with your Eliza agent runtime
 */

// ---------------------------------------------------------------------------
// Types — Eliza action schema
// ---------------------------------------------------------------------------

export interface ElizaParameterSchema {
  type: string
  description?: string
  required?: boolean
  enum?: string[]
}

export interface ElizaActionSchema {
  /** Unique action name — matches the original tool name */
  name: string
  /** Human-readable description shown to the LLM */
  description: string
  /** Named parameter definitions */
  parameters: Record<string, ElizaParameterSchema>
  /** Required parameter keys */
  required: string[]
  /** Async handler function — same signature as LangChain tool.func */
  handler: (input: Record<string, unknown>) => Promise<string>
  /** Metadata for Eliza runtime routing */
  metadata: {
    source: 'nexus-intelligence'
    version: '1'
    originalName: string
  }
}

// ---------------------------------------------------------------------------
// LangChain tool shape (subset we consume)
// ---------------------------------------------------------------------------

export interface LangChainToolLike {
  name: string
  description: string
  schema?: {
    type?: string
    properties?: Record<string, { type: string; description?: string; enum?: string[] }>
    required?: string[]
  }
  func: (input: Record<string, unknown>) => Promise<string>
}

// ---------------------------------------------------------------------------
// Adapter
// ---------------------------------------------------------------------------

/**
 * Convert an array of LangChain-style tool definitions into Eliza action payloads.
 *
 * @param tools - Array of LangChain tool definitions (from NexusToolkit.getLangChainTools)
 * @returns Array of Eliza-compatible action schemas
 */
export function elizaAdapter(tools: LangChainToolLike[]): ElizaActionSchema[] {
  return tools.map(tool => {
    const properties = tool.schema?.properties ?? {}
    const requiredKeys = tool.schema?.required ?? []

    const parameters: Record<string, ElizaParameterSchema> = {}
    for (const [key, def] of Object.entries(properties)) {
      parameters[key] = {
        type: def.type,
        description: def.description,
        required: requiredKeys.includes(key),
        ...(def.enum ? { enum: def.enum } : {}),
      }
    }

    return {
      name: tool.name,
      description: tool.description,
      parameters,
      required: requiredKeys,
      handler: async (input: Record<string, unknown>) => {
        // Delegate to the original LangChain tool func — same execution path
        return tool.func(input)
      },
      metadata: {
        source: 'nexus-intelligence' as const,
        version: '1' as const,
        originalName: tool.name,
      },
    }
  })
}

/**
 * Convert a single LangChain tool definition into an Eliza action payload.
 */
export function elizaAdapterSingle(tool: LangChainToolLike): ElizaActionSchema {
  return elizaAdapter([tool])[0]
}
